#!/bin/sh
HC=${1:?usage: hetest.sh <hc> [test-dir]}; D=${2:-$(dirname "$0")/../../hc/test}; L=${HC_LIB:-$(dirname "$0")/../../hc/lib}; W=$(mktemp -d); p=0; f=0
for t in "$D"/*.he; do n=$(basename "$t" .he); for m in c native debug; do rm -f "$W/x" "$W/x.c"; case $m in c) HC_LIB=$L "$HC" "$t" "$W/x.c" 2>"$W/e" && clang -O1 -fwrapv -w -I"$L/.." "$W/x.c" -o "$W/x" -lm 2>>"$W/e";; native) HC_LIB=$L "$HC" "$t" "$W/x" --native 2>"$W/e";; debug) HC_LIB=$L "$HC" "$t" "$W/x" --native --debug 2>"$W/e";; esac; if [ -x "$W/x" ] && "$W/x" 2>&1 | cmp -s - "$D/$n.out"; then p=$((p+1)); else f=$((f+1)); echo "FAIL $n ($m): $(head -c 300 "$W/e")"; fi; done; if HC_LIB=$L "$HC" check --all "$t" >/dev/null 2>"$W/e"; then p=$((p+1)); else f=$((f+1)); echo "FAIL $n (check --all): $(head -c 300 "$W/e")"; fi; done
mkdir "$W/l" && ln -s "$(realpath "$L")"/* "$W/l/" && mkdir "$W/l/s" && printf 'namespace b\nf() int: nope()\n' > "$W/l/s/b.he" && printf 'use b\nmain(): return\n' > "$W/l/s/m.he"; if HC_LIB="$W/l" "$HC" check --all "$W/l/s/m.he" >/dev/null 2>&1; then f=$((f+1)); echo "FAIL check --all skipped a lib module beside the root"; else p=$((p+1)); fi
rm -rf "$W"; echo "hetest: $p pass, $f fail"; [ $f = 0 ]
